import{_ as t,o as n,c as o,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Frontend Guidelines","description":"Rules for React development, component splitting, testing, and UX patterns.","frontmatter":{"isInternal":true,"type":"Specification","title":"Frontend Guidelines","description":"Rules for React development, component splitting, testing, and UX patterns.","tags":["frontend","react","guidelines","ux","testing","specification"]},"headers":[],"relativePath":"specs/frontend-guidelines.md","filePath":"specs/frontend-guidelines.md"}'),i={name:"specs/frontend-guidelines.md"};function a(l,e,r,c,d,p){return n(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="sanjeev-ai-frontend-guidelines" tabindex="-1">Sanjeev AI: Frontend Guidelines <a class="header-anchor" href="#sanjeev-ai-frontend-guidelines" aria-label="Permalink to &quot;Sanjeev AI: Frontend Guidelines&quot;">​</a></h1><p>To maintain a scalable, readable, and highly performant codebase, all React development in this project must adhere to the following guidelines.</p><h2 id="_1-file-size-component-splitting" tabindex="-1">1. File Size &amp; Component Splitting <a class="header-anchor" href="#_1-file-size-component-splitting" aria-label="Permalink to &quot;1. File Size &amp; Component Splitting&quot;">​</a></h2><ul><li><strong>Maximum File Size:</strong> No component file should exceed <strong>300-400 lines of code</strong>. If a file exceeds this limit, it is doing too much.</li><li><strong>Single Responsibility Principle:</strong> A component should do one thing well. If a component handles complex state, renders a complex UI, <em>and</em> contains multiple sub-views (e.g., Modals), it must be split.</li><li><strong>UI vs Logic:</strong> Separate complex business logic from UI rendering using Custom Hooks (e.g., <code>useStudioState</code>, <code>useWorkflow</code>).</li></ul><h2 id="_2-directory-structure" tabindex="-1">2. Directory Structure <a class="header-anchor" href="#_2-directory-structure" aria-label="Permalink to &quot;2. Directory Structure&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>  ├── components/      # Reusable UI components (Buttons, Inputs)</span></span>
<span class="line"><span>  ├── features/        # Feature-specific modules (e.g., /studio, /auth)</span></span>
<span class="line"><span>  │   └── studio/</span></span>
<span class="line"><span>  │       ├── hooks/   # Custom hooks (e.g., useDirector.ts)</span></span>
<span class="line"><span>  │       ├── ui/      # Feature sub-components (e.g., StudioHeader.tsx, AutomationModal.tsx)</span></span>
<span class="line"><span>  │       └── UnifiedStudio.tsx # The Main Container</span></span>
<span class="line"><span>  ├── pages/           # Route-level components</span></span>
<span class="line"><span>  ├── hooks/           # Global hooks (e.g., useAuth)</span></span>
<span class="line"><span>  └── utils/           # Helper functions</span></span></code></pre></div><h2 id="_3-sub-component-extraction-rules" tabindex="-1">3. Sub-Component Extraction Rules <a class="header-anchor" href="#_3-sub-component-extraction-rules" aria-label="Permalink to &quot;3. Sub-Component Extraction Rules&quot;">​</a></h2><p>When extracting components from a large monolith (like <code>UnifiedStudio.tsx</code>), follow these steps:</p><ol><li><strong>Extract Modals:</strong> Popups and modals (e.g., Publish Modal, Automation Modal, Cast Modal) should always be their own files. They usually only rely on a few props (<code>isOpen</code>, <code>onClose</code>, <code>onSubmit</code>).</li><li><strong>Extract Independent UI Sections:</strong> A header toolbar, a progress stepper, or a sidebar should be isolated into components like <code>&lt;StudioHeader /&gt;</code> and <code>&lt;WorkflowStepper /&gt;</code>.</li><li><strong>Pass Callbacks, not Setters:</strong> Avoid passing <code>setState</code> functions deep into children. Pass semantic callback functions like <code>onLaunchAutomation</code> or <code>onPublish</code>.</li></ol><h2 id="_4-state-management" tabindex="-1">4. State Management <a class="header-anchor" href="#_4-state-management" aria-label="Permalink to &quot;4. State Management&quot;">​</a></h2><ul><li>Group related state into custom hooks.</li><li>Avoid passing more than 4-5 props to a component. If you need more, consider passing a config object or using a context provider.</li></ul><h2 id="_5-styling" tabindex="-1">5. Styling <a class="header-anchor" href="#_5-styling" aria-label="Permalink to &quot;5. Styling&quot;">​</a></h2><ul><li>Continue using Tailwind CSS.</li><li>Avoid inline styles unless absolutely necessary (e.g., dynamic width for progress bars).</li><li>Keep classes readable by extracting long class strings into constants or using <code>clsx</code>/<code>tailwind-merge</code> if conditional logic is complex.</li></ul><h2 id="_6-unit-testing-testability" tabindex="-1">6. Unit Testing &amp; Testability <a class="header-anchor" href="#_6-unit-testing-testability" aria-label="Permalink to &quot;6. Unit Testing &amp; Testability&quot;">​</a></h2><p>Splitting components is critical for achieving high test coverage and maintainability:</p><ul><li><strong>Test UI in Isolation:</strong> &quot;Dumb&quot; UI components (e.g., <code>WorkflowStepper.tsx</code>) can be tested purely with mock props (e.g., passing a fake <code>workflowState</code> object) without needing to mock Firebase, Auth, or complex contexts.</li><li><strong>Test Logic in Isolation:</strong> Custom Hooks (e.g., <code>useAutomation.ts</code>) can be tested independently of the UI using libraries like <code>@testing-library/react-hooks</code>.</li><li><strong>Mocking:</strong> The smaller the component, the less mocking is required. Monolithic components often require incredibly complex test setups that break easily.</li><li><strong>Test File Conventions:</strong> Name your unit tests <code>*.test.ts/tsx</code> and your Playwright tests <code>*.spec.ts/tsx</code>. These are strictly excluded in <code>tsconfig.app.json</code> from the production build to ensure testing libraries (like <code>vi</code>) do not contaminate or break the main application build step.</li></ul><h3 id="testing-environment-strategy" tabindex="-1">Testing Environment Strategy <a class="header-anchor" href="#testing-environment-strategy" aria-label="Permalink to &quot;Testing Environment Strategy&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>CRITICAL RULE FOR AI AGENTS:</strong></p><ol><li><strong>Local Testing:</strong> When running or writing tests locally (both E2E Playwright tests and Vitest Unit/Integration tests), they MUST run against the <strong>Local Firebase Emulators</strong>.</li><li><strong>GitHub CI Testing:</strong> When tests run in GitHub Actions (after a push), they will run against the live <code>sanjeev-ai-staging</code> or <code>sanjeev-ai</code> Firebase projects using Custom Tokens. Do NOT configure local tests to hit live Firebase databases.</li></ol></div><h2 id="_7-in-file-documentation-self-contained-context" tabindex="-1">7. In-File Documentation (Self-Contained Context) <a class="header-anchor" href="#_7-in-file-documentation-self-contained-context" aria-label="Permalink to &quot;7. In-File Documentation (Self-Contained Context)&quot;">​</a></h2><p>To ensure independent future feature analysis is easy, <strong>all code files must contain a self-contained documentation block at the top of the file</strong>. This block must include:</p><ol><li><strong>Description:</strong> What this file does.</li><li><strong>Parent Component(s):</strong> Where this component/hook is used (e.g., consumed by <code>UnifiedStudio.tsx</code>).</li><li><strong>Dependencies / Children:</strong> What other services or sub-components this file relies on (e.g., depends on Firebase Firestore, renders <code>VideoScrubber</code>).</li></ol><p><strong>Example:</strong></p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/**</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@file</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> StudioToolbar.tsx</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@description</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> Renders the top-right action buttons in the Unified Studio (Automate, Director, Audio, Export).</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@parent</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> UnifiedStudio.tsx (Main Container)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@dependencies</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> React, SanjeevAI Icon Components</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> */</span></span></code></pre></div><h2 id="_8-ux-guidelines-for-mobile-and-desktop" tabindex="-1">8. UX Guidelines for Mobile and Desktop <a class="header-anchor" href="#_8-ux-guidelines-for-mobile-and-desktop" aria-label="Permalink to &quot;8. UX Guidelines for Mobile and Desktop&quot;">​</a></h2><p>To ensure consistency and robustness across our interfaces, follow these UX/UI patterns:</p><h3 id="responsive-header-layouts" tabindex="-1">Responsive Header Layouts <a class="header-anchor" href="#responsive-header-layouts" aria-label="Permalink to &quot;Responsive Header Layouts&quot;">​</a></h3><p>Complex headers (Title + Tabs + Actions) must not break or overflow on small screens. Use CSS Flexbox ordering to control responsive wrapping:</p><ul><li><strong>Top Row (Mobile):</strong> Keep the <strong>Title</strong> (<code>order-1</code>) and <strong>Action Buttons</strong> (e.g., <code>⋮</code>, <code>X</code>) (<code>order-2</code>, <code>ml-auto</code>) on the top line.</li><li><strong>Second Row (Mobile):</strong> Push <strong>Tabs</strong> (<code>order-3</code>, <code>w-full</code>) to wrap onto their own full-width line below the title.</li><li><strong>Desktop:</strong> The same markup can gracefully reflow into a single line (<code>w-auto</code> for tabs, <code>order-2</code> for tabs, <code>order-3</code> for actions) simply by toggling breakpoints (e.g., <code>sm:order-2</code>).</li></ul><h3 id="preventing-button-crowding" tabindex="-1">Preventing &quot;Button Crowding&quot; <a class="header-anchor" href="#preventing-button-crowding" aria-label="Permalink to &quot;Preventing &quot;Button Crowding&quot;&quot;">​</a></h3><ul><li><strong>Truncation:</strong> Always allow titles and large text blocks to shrink (<code>min-w-0</code>, <code>shrink</code>) and <code>truncate</code> with ellipses rather than pushing interactive elements off-screen.</li><li><strong>Dropdown Menus:</strong> If action buttons (Automate, Export, Import, etc.) fight for horizontal space, wrap them into a &quot;More Options&quot; (<code>⋮</code> or <code>MoreVertical</code>) dropdown menu. Trigger this collapse early (e.g., at the <code>xl</code> breakpoint or permanently) rather than relying on horizontal scrolling for critical actions.</li></ul><h3 id="consistency-in-create-new-actions" tabindex="-1">Consistency in &quot;Create New&quot; Actions <a class="header-anchor" href="#consistency-in-create-new-actions" aria-label="Permalink to &quot;Consistency in &quot;Create New&quot; Actions&quot;">​</a></h3><ul><li><strong>Persistent Access:</strong> When managing lists of assets (Scripts, Characters, Locations), users must <em>always</em> be able to append a new item without relying solely on an empty-state screen or a hidden menu.</li><li><strong>Pattern:</strong> Include a prominent <code>+ Add Line</code> button at the bottom of the script list, or a large dashed <code>➕ Add [Item]</code> card at the very end of asset grids.</li><li><strong>Empty States:</strong> Empty states should also explicitly offer a primary button to create the very first asset from scratch.</li></ul><h3 id="layout-stability" tabindex="-1">Layout Stability <a class="header-anchor" href="#layout-stability" aria-label="Permalink to &quot;Layout Stability&quot;">​</a></h3><ul><li>Avoid <code>absolute</code> positioning for major layout toggles (like Tab Switchers). Place them in the normal document flow (e.g., as a dedicated block or flex column) to prevent z-index wars, overlapping, or cut-offs with scrolling containers.</li></ul>`,34)])])}const g=t(i,[["render",a]]);export{h as __pageData,g as default};
